/* eslint-disable */
// ship-coins v1 — the store's order.paid (schema 2) request, verified before
// anything reads it. Every failure in this workflow THROWS: the Error Workflow
// sends the Telegram alert and the store, seeing no acknowledgement, retries
// with whatever is still unplaced. There is no in-flow failure rail.
//
// The signature covers the exact bytes the store sent (timestamp, event id and
// raw body joined by newlines, HMAC-SHA256 with N8N_ORDER_PAID_SECRET), so the
// Webhook node must run with "Raw Body" on. Verification reads those bytes and
// never a re-serialised copy: PHP writes 1.0 where JavaScript writes 1, and
// escapes Arabic where JavaScript does not.
//
// Keys and secrets live in the Config node (Edit Fields) that sits between
// the Webhook and this node - the instance has neither environment variables
// nor $vars (owner decision, 2026-09-14). A value still reading CONFIGURE_...
// is a value nobody pasted.

const crypto = require('crypto');

const config = $('Config').first().json || {};
const requiredKeys = [
    'N8N_ORDER_PAID_KEY',
    'N8N_ORDER_PAID_SECRET',
    'N8N_FULFILLMENT_KEY',
    'N8N_FULFILLMENT_SECRET',
    'FFT_API_USER',
    'FFT_API_KEY',
    'UTT_API_KEY',
];
const missingKeys = requiredKeys.filter((name) => !config[name] || /^CONFIGURE_/.test(String(config[name])));
if (missingKeys.length) {
    throw new Error(
        `[verify] not set in the Config node: ${missingKeys.join(', ')}`,
    );
}
if (String(config.N8N_ORDER_PAID_SECRET).length < 32) {
    throw new Error('[verify] N8N_ORDER_PAID_SECRET is shorter than 32 characters');
}

// Read from the Webhook node by name: the Config node sits in between and
// passes the request through, but the raw bytes are authoritative here.
const item = $('Webhook').first();
const json = item.json || {};
const headers = json.headers || {};

function header(name) {
    const value = headers[name] ?? headers[name.toLowerCase()];
    return String(Array.isArray(value) ? value[0] : value ?? '');
}

function equal(left, right) {
    const a = Buffer.from(String(left), 'utf8');
    const b = Buffer.from(String(right), 'utf8');
    return a.length === b.length && crypto.timingSafeEqual(a, b);
}

// The raw body. In n8n's default (memory) binary mode the Webhook node hands
// it over base64-encoded under binary.data.data; the filesystem mode hands a
// file id instead, which the helper below resolves when it exists (it reads
// this node's input, so the Config node must keep "Include Binary" on).
async function rawBody() {
    const helpers = typeof this === 'object' && this !== null ? this.helpers : null;
    if (helpers && typeof helpers.getBinaryDataBuffer === 'function') {
        try {
            const buffer = await helpers.getBinaryDataBuffer(0, 'data');
            if (buffer && buffer.length) return buffer.toString('utf8');
        } catch (error) {
            // fall through to the in-memory shape
        }
    }
    const binary = item.binary && item.binary.data;
    if (binary && binary.id) {
        // Stored outside memory and the helper could not read it: the
        // in-memory field holds a mode marker, not the bytes.
        return null;
    }
    if (binary && typeof binary.data === 'string' && binary.data !== '') {
        return Buffer.from(binary.data, 'base64').toString('utf8');
    }
    if (typeof json.rawBody === 'string') return json.rawBody;
    return null;
}

const raw = await rawBody.call(this);
if (raw === null) {
    throw new Error(
        '[verify] the raw request body is unavailable - turn on "Raw Body" in the Webhook node options',
    );
}

const key = header('x-arabut-key');
const timestamp = header('x-arabut-timestamp');
const eventId = header('x-arabut-event');
const signature = header('x-arabut-signature');

if (!equal(key, config.N8N_ORDER_PAID_KEY)) {
    throw new Error('[verify] X-ArabUT-Key does not match N8N_ORDER_PAID_KEY');
}
if (!/^\d{10}$/.test(timestamp) || Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) {
    throw new Error('[verify] X-ArabUT-Timestamp is outside the five-minute window');
}
const expected = crypto
    .createHmac('sha256', config.N8N_ORDER_PAID_SECRET)
    .update(`${timestamp}\n${eventId}\n${raw}`)
    .digest('hex');
if (!equal(signature, expected)) {
    throw new Error('[verify] X-ArabUT-Signature does not match the request body');
}

let event;
try {
    event = JSON.parse(raw);
} catch (error) {
    throw new Error('[verify] the request body is not JSON');
}

if (!event || event.eventType !== 'order.paid') {
    throw new Error(`[verify] unexpected eventType ${event && event.eventType}`);
}
if (Number(event.schemaVersion) !== 2) {
    throw new Error(`[verify] unexpected schemaVersion ${event && event.schemaVersion}; this workflow reads schema 2`);
}
if (event.eventId !== eventId) {
    throw new Error('[verify] X-ArabUT-Event does not match the body eventId');
}
const order = event.data;
if (!order || typeof order.order_number !== 'string' || !Array.isArray(order.items) || order.items.length === 0) {
    throw new Error('[verify] the request carries no items to place');
}

return [{ json: { eventId, order, receivedAt: new Date().toISOString() } }];

/* eslint-disable */
// ship-coins v1 — one shipment per run.
//
// v14 read one coins item per order and merged a challenge's coins with the
// coins bought beside it into ONE supplier order, on purpose: two shipments to
// one EA account at once are two bots on one account. This node keeps that
// rule and generalises it only as far as the store's data forces: the items
// are grouped by EA account and platform, the first group becomes the
// shipment, and any other group is left for the store's retry - the store
// re-reads the order before every send and omits what is already placed, so
// answering "not acknowledged" with items remaining brings them next time.
//
// The output field names are v14's own (amountK, calculatedMaxPrice,
// startCoins, eaBackup1..3, isSlowShipping ...), so the Supplier Decision
// Engine and the HTTP nodes copied from v14 read them unchanged.

const order = $('Verify Request').first().json.order;
const orderId = order.order_number;

function fail(message) {
    throw new Error(`[plan] order ${orderId}: ${message}`);
}

const groups = new Map();

for (const item of order.items) {
    const account = item.account || {};
    const email = String(account.ea_email || '').trim().toLowerCase();
    const platform = String(item.supplier_platform || '');

    if (!email || !account.ea_password) fail(`item ${item.order_item_public_id} carries no EA account`);
    if (platform !== 'PS' && platform !== 'PC') fail(`item ${item.order_item_public_id} is on ${item.platform || '?'}, which no supplier serves`);
    if (item.service !== 'coins' && item.service !== 'sbc') fail(`item ${item.order_item_public_id} is a ${item.service}, which no supplier delivers`);

    const key = `${email}|${platform}`;
    if (!groups.has(key)) groups.set(key, { email, platform, account, items: [] });
    groups.get(key).items.push(item);
}

const [shipment, ...rest] = [...groups.values()];
const codes = Array.isArray(shipment.account.backup_codes)
    ? shipment.account.backup_codes.filter((code) => typeof code === 'string' && code !== '')
    : [];

const coinsItems = [];
const sbcItems = [];
let calculatedMaxPrice = 0;

for (const item of shipment.items) {
    const budget = Number(item.budget && item.budget.max_eur_per_100k) || 0;
    if (budget <= 0) fail(`item ${item.order_item_public_id} carries no budget`);
    // v14 priced a merged shipment by its total tier; the store prices each
    // item, and the larger ceiling is the one the merged shipment may spend.
    calculatedMaxPrice = Math.max(calculatedMaxPrice, budget);

    if (item.service === 'coins') {
        const quantity = Number(item.coins && item.coins.quantity) || 0;
        if (quantity <= 0) fail(`item ${item.order_item_public_id} has no coins quantity`);
        coinsItems.push({
            orderItemPublicId: item.order_item_public_id,
            amountK: Math.round(quantity / 1000),
            delivery: (item.coins && item.coins.delivery) || null,
        });
    } else {
        const setID = Number(item.sbc && item.sbc.set_id) || 0;
        if (setID <= 0) fail(`item ${item.order_item_public_id} names no challenge`);
        sbcItems.push({
            orderItemPublicId: item.order_item_public_id,
            sbcSetID: setID,
            sbcTimesToSolve: Math.max(1, Number(item.sbc && item.sbc.times_to_solve) || 1),
        });
    }
}

const extraCoinsK = coinsItems.reduce((sum, entry) => sum + entry.amountK, 0);
const balance = Number(shipment.account.current_balance);

return [{
    json: {
        orderId,
        orderPublicId: order.order_public_id,
        customerName: String(order.customer_name || '').trim() || 'ArabUT',
        platform: shipment.platform,
        eaEmail: shipment.email,
        eaPass: String(shipment.account.ea_password),
        eaBackup1: codes[0] || '',
        eaBackup2: codes[1] || '',
        eaBackup3: codes[2] || '',
        // v14: an unknown balance was taken as 200,000.
        startCoins: Number.isFinite(balance) && balance > 0 ? Math.round(balance) : 200000,
        calculatedMaxPrice,
        coinsItems,
        sbcItems,
        extraCoinsK,
        // The coins-only amount; a challenge shipment's amount is settled once
        // FFT has priced the challenge (SBC: Match & Validate).
        amountK: extraCoinsK,
        needsChallengePricing: sbcItems.length > 0,
        // v14: slow shipping only ever applied to a plain coins order.
        isSlowShipping: sbcItems.length === 0 && coinsItems.every((entry) => entry.delivery === 'normal'),
        transferMethod: 'targetedSnipe',
        itemIds: shipment.items.map((item) => item.order_item_public_id),
        remainingGroups: rest.length,
    },
}];

/* eslint-disable */
// ship-coins v1 — v14's "SBC: Match & Validate", with the challenge list read
// from the shipment instead of Router Logic1 and the budget taken from the
// store instead of the price sheet. The matching, the unpriced-challenge
// refusal and the coin arithmetic are v14's.
//
// FFT prices a challenge live (consolePrice / pcPrice, in coins), so the
// coins a challenge shipment must carry are only known here.

// ── 1. إعادة بناء مصفوفة التحديات من كل عناصر الـ input ──
const allInputItems = $input.all();
let availableSBCs = null;

if (allInputItems.length > 1) {
  availableSBCs = allInputItems.map(item => item.json);
}
if (!availableSBCs && allInputItems.length === 1) {
  const firstJson = allInputItems[0].json;
  if (Array.isArray(firstJson)) availableSBCs = firstJson;
  else if (firstJson.data && Array.isArray(firstJson.data)) availableSBCs = firstJson.data;
  else if (firstJson.sbcs && Array.isArray(firstJson.sbcs)) availableSBCs = firstJson.sbcs;
}
if (!availableSBCs && allInputItems.length === 1) {
  const firstJson = allInputItems[0].json;
  if (firstJson.setID !== undefined) availableSBCs = [firstJson];
}

const shipment = $('Plan Shipment').first().json;
const orderId = shipment.orderId;

if (!availableSBCs || !Array.isArray(availableSBCs) || availableSBCs.length === 0) {
  throw new Error(`[sbc] order ${orderId}: فشل قراءة قائمة التحديات. عدد العناصر المستقبلة: ${allInputItems.length}`);
}

const sbcRouterItems = shipment.sbcItems || [];
if (sbcRouterItems.length === 0) {
  throw new Error(`[sbc] order ${orderId}: لم يتم العثور على أي SBC في بيانات الطلب`);
}

const platform = shipment.platform || 'PS';

// ── 3. التحقق من كل SBC مطلوب ──
const sbcSetIDs = [];
let totalCoinsK = 0;
let totalChallengeAmount = 0;
const sbcNames = [];

for (const routerItem of sbcRouterItems) {
  const setID = routerItem.sbcSetID;
  const sbcMatch = availableSBCs.find(sbc => Number(sbc.setID) === Number(setID));
  if (!sbcMatch) throw new Error(`[sbc] order ${orderId}: التحدي غير موجود: setID ${setID}`);

  const coinPrice = platform === 'PC'
    ? parseFloat(sbcMatch.pcPrice)
    : parseFloat(sbcMatch.consolePrice);

  if (!coinPrice || coinPrice <= 0) {
    const rawPrice = platform === 'PC' ? sbcMatch.pcPrice : sbcMatch.consolePrice;
    throw new Error(`[sbc] order ${orderId}: FFT ما مسعّر هذا التحدي حالياً (السعر المستلم: ${rawPrice}) — غالباً غير قابل للحل الآلي: "${sbcMatch.sbcName}" [منصة ${platform}]. الطلب يحتاج حل يدوي.`);
  }

  const coinsPerSolveK = Math.ceil(coinPrice / 1000);
  const timesToSolve = routerItem.sbcTimesToSolve || 1;

  totalCoinsK += coinsPerSolveK * timesToSolve;
  totalChallengeAmount += (sbcMatch.challengeAmount || 0) * timesToSolve;
  sbcNames.push(sbcMatch.sbcName);

  sbcSetIDs.push({
    setID: sbcMatch.setID,
    sbcName: sbcMatch.sbcName,
    challengeAmount: sbcMatch.challengeAmount,
    expiry: sbcMatch.expiry,
    coinsPerSolveK,
    timesToSolve,
    orderItemPublicId: routerItem.orderItemPublicId,
  });
}

// ── 4. إضافة الكوينز الإضافية (لو فيه طلب كوينز مدمج) ──
const extraCoinsK = shipment.extraCoinsK || 0;
const totalAmountK = totalCoinsK + extraCoinsK;

// ── 6. إرجاع عنصر واحد مدمج ──
return [{
  json: {
    ...shipment,
    sbcSetIDs,
    sbcName: sbcNames.join(' + '),
    challengeAmount: totalChallengeAmount,
    amountK: totalAmountK,
    extraCoinsK,
    totalSBCsFound: availableSBCs.length,
  }
}];

/* eslint-disable */
// ship-coins v1 — the one shipment this run places, whichever branch built it.
//
// v14's HTTP nodes read `$('Coins Item')` or `$('SBC: Match & Validate')`
// depending on the path; here both paths end in this node so every later
// expression reads `$('Shipment')`. Nothing is computed: this is the named
// hand-off point, and the last place a bad shipment can be refused before a
// supplier is asked anything.

const shipment = $input.first().json;
const orderId = shipment.orderId;

if (!(Number(shipment.amountK) > 0)) {
    throw new Error(`[shipment] order ${orderId}: the shipment carries no coins`);
}
if (!(Number(shipment.calculatedMaxPrice) > 0)) {
    throw new Error(`[shipment] order ${orderId}: the shipment carries no budget`);
}
if (!Array.isArray(shipment.itemIds) || shipment.itemIds.length === 0) {
    throw new Error(`[shipment] order ${orderId}: the shipment names no order items`);
}

return [{ json: shipment }];

/* eslint-disable */
// ══════════════════════════════════════════════════════════════════════
// SUPPLIER DECISION ENGINE — UTT vs FFT for a coins order.
//
// v14's node, verbatim, with two renames: the shipment is `$('Shipment')`
// (v14 read `$('Coins Item')` on the coins path and
// `$('SBC: Match & Validate')` on the challenge path; both end in Shipment
// here) and the budget it reads was computed by the store rather than read
// from the price sheet. Everything below the input block is v14.11.
//
// PRICE UNITS: calculatedMaxPrice and UTT stock.price are BOTH EUR per 100K.
// COMBINED STOCKS (v14.6, validated live): UTT pools capacity across the stocks
// listed in publicSale, so we greedily build the CHEAPEST combination whose combined
// getMaxOrderPrediction covers the order. MAX_COMBO 10 = the EA card budget per
// order/36h (raised from 4 on 2026-07-04); the publicSale stock list itself is
// unlimited, so failover pads are free until a card is actually used, and compare
// FFT against the BLENDED price of that combination (marginal-gain weighted).
// COOLDOWN: orderCardsRemaining < 3 → force UTT (cross-system ban protection).
// PARTIAL (v14.11): neither covers fully → whoever delivers MORE right now
// (FFT keeps ties — it tops up; UTT must beat FFT by 20%+). Full-coverage FFT
// price-win additionally needs 10% preview headroom (owner decision 2026-07-04).
// ══════════════════════════════════════════════════════════════════════
const src = $('Shipment').first().json;
let uttStocksData = {};
try { uttStocksData = $('UTT: Get Stocks').first().json || {}; } catch (e) {}

const amountK = src.amountK;
const orderAmountCoins = amountK * 1000;
const platform = src.platform;
const startCoins = src.startCoins || 200000;
const maxPrice = Number(src.calculatedMaxPrice) || 0;
const stocks = uttStocksData.stocks || [];
const ratioEuroUsd = parseFloat(uttStocksData.ratioEuroUsd) || 1.15;

// FFT preview balance ladder (kept as-is per business decision 2026-07)
const topUpTarget = platform === 'PC' ? 0 : (
    amountK <= 300 ? 20000 : amountK <= 500 ? 50000 : amountK <= 1000 ? 200000
  : amountK <= 1500 ? 300000 : amountK <= 2000 ? 300000 : 400000);
const fftCustomerBalance = Math.max(startCoins, topUpTarget);

// keep stocks big enough to matter in a combination (not: cover alone)
const minUseful = Math.max(100000, orderAmountCoins * 0.15);
const validStocks = stocks
  .filter(s => (parseFloat(s.averageCoinsAvailable) * 5) >= minUseful)
  .filter(s => parseFloat(s.price) <= maxPrice)
  .sort((a, b) => parseFloat(a.price) - parseFloat(b.price))
  .slice(0, 20);

const CONFIG = $('Config').first().json;
const UTT_API_KEY = CONFIG.UTT_API_KEY;
const uttPlatform = platform.toLowerCase();
const MAX_COMBO = 10;      // = card budget per order/36h (was 4); stock list is unlimited
const MAX_PREDICTION_CALLS = 12;

let forcedUTT = false;
let cardsRemaining = null;
let combo = [];            // {numberStock, price(str), marginal}
let comboPred = 0;
let calls = 0;

async function predict(sectionString) {
  calls++;
  const result = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://utautotransfer.com/api/getMaxOrderPrediction',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: `apiKey=${UTT_API_KEY}&platform=${uttPlatform}&orderMethod=public&stockSection=${encodeURIComponent(sectionString)}&startCoins=${startCoins}&email=${encodeURIComponent(src.eaEmail)}`,
  });
  return result;
}

for (const stock of validStocks) {
  if (calls >= MAX_PREDICTION_CALLS || combo.length >= MAX_COMBO) break;
  if (comboPred >= orderAmountCoins) break;
  const tentative = [...combo, { numberStock: stock.numberStock, price: stock.price }];
  const section = tentative.map(s => `${s.numberStock},${s.price}`).join(',');
  try {
    const r = await predict.call(this, section);
    const pred = r.maxTransferable || 0;
    if (cardsRemaining === null) cardsRemaining = r.orderCardsRemaining ?? 10;
    if ((r.orderCardsRemaining ?? 10) < 3) forcedUTT = true;
    const marginal = pred - comboPred;
    if (marginal > 50000) {           // stock adds real capacity → keep it
      combo = tentative;
      combo[combo.length - 1].marginal = marginal;
      comboPred = pred;
    }
  } catch (e) { continue; }
}

// blended price = marginal-gain-weighted average over what the order actually uses
let blendedPrice = null;
if (combo.length) {
  let remaining = orderAmountCoins, costSum = 0, used = 0;
  for (const c of combo) {
    const take = Math.min(c.marginal, remaining);
    costSum += take * parseFloat(c.price);
    used += take; remaining -= take;
    if (remaining <= 0) break;
  }
  blendedPrice = used > 0 ? Math.round((costSum / used) * 1000) / 1000 : parseFloat(combo[0].price);
}

const fullCoverage = comboPred >= orderAmountCoins && combo.length > 0;

// pad pure-failover backups (unused cheapest stocks) up to 8 entries total —
// list is unlimited and a pad only consumes a card if UTT actually switches to it
// (built whenever a combo exists — UTT can now also win partial-coverage orders)
let publicSaleString = null;
if (combo.length) {
  const usedStocks = new Set(combo.map(c => `${c.numberStock},${c.price}`));
  const pads = validStocks
    .map(s => `${s.numberStock},${s.price}`)
    .filter(k => !usedStocks.has(k));
  const parts = combo.map(c => `${c.numberStock},${c.price}`);
  while (parts.length < 8 && pads.length) parts.push(pads.shift());
  publicSaleString = parts.join(',');
}

// ── SUPPLIER DECISION ──
let supplier = '';
let fftMaxPossibleK = 0;
let fftTestPrice = null;

const askFFT = async (testPrice) => {
  const fftResult = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://futtransfer.top/maxOrderPreviewAPI',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ apiUser: CONFIG.FFT_API_USER, apiKey: CONFIG.FFT_API_KEY,
      platform, customerBalance: fftCustomerBalance, ownSenders: 0, maxPrice: testPrice, riskLevel: 10 }),
  });
  return typeof fftResult === 'string' ? JSON.parse(fftResult) : fftResult;
};

if (forcedUTT) {
  supplier = combo.length > 0 ? 'UTT' : 'FFT';
} else if (!fullCoverage) {
  // neither side guaranteed → send to whoever moves more coins RIGHT NOW
  const uttK = Math.round(comboPred / 1000);
  try {
    const parsed = await askFFT(maxPrice);
    fftMaxPossibleK = (parsed.success && parsed.maxPossibleK) || 0;
    if (fftMaxPossibleK >= amountK) supplier = 'FFT';                            // FFT covers fully after all
    else if (combo.length > 0 && uttK > fftMaxPossibleK * 1.2) supplier = 'UTT'; // UTT clearly ahead
    else supplier = 'FFT';                                                        // tie or FFT ahead → FFT tops up
  } catch (e) { supplier = 'FFT'; }
} else {
  fftTestPrice = Math.round((blendedPrice - 0.09) * 100) / 100;
  if (fftTestPrice <= 0) {
    supplier = 'UTT';
  } else {
    try {
      const parsed = await askFFT(fftTestPrice);
      fftMaxPossibleK = parsed.maxPossibleK || 0;
      supplier = (parsed.success && fftMaxPossibleK >= amountK * 1.10) ? 'FFT' : 'UTT';
    } catch (e) { supplier = 'UTT'; }
  }
}

return [{ json: {
  supplier,
  forcedUTT,
  isPartialFulfillment: !!(supplier === 'UTT' && comboPred < orderAmountCoins),
  uttPublicSaleString: publicSaleString,
  uttPrice: blendedPrice,
  uttComboStocks: combo.map(c => `${c.numberStock}@${c.price}(+${Math.round(c.marginal / 1000)}K)`).join(' '),
  uttMaxK: comboPred ? Math.round(comboPred / 1000) : null,
  uttCardsRemaining: cardsRemaining,
  fftTestPrice, fftMaxK: fftMaxPossibleK || null, fftCustomerBalance,
  amountK, platform, startCoins,
  calculatedMaxPrice: src.calculatedMaxPrice,
  ratioEuroUsd,
  stocksTested: calls,
  totalStocksAvailable: stocks.length,
  orderId: src.orderId,
}}];

