/* eslint-disable */
// ship-coins v1 — the supplier's reference for the shipment just placed.
//
// The first half of v14's "Coins: Prepare Poll" (the second half froze the
// poll context, and the poll now lives in the store). UTT answers
// `order.idOrder`; FFT answers `data.orderID`, sometimes as a JSON string.
// No id from either is an in-band rejection - HTTP 200 with an error body -
// and v14 flagged it `chargeFailed`; here it throws, so the ops alert names
// the order and the store retries the shipment later.
//
// One output item per order item the shipment funds: the placement report
// is filed once per item with the same reference (the store's shared-
// shipment rule).

const shipment = $('Shipment').first().json;
const orderId = shipment.orderId;

let supplier = null, reference = null, rawError = null;
try {
  const u = $('UTT: Add Order Public').first().json;
  if (u && u.order && u.order.idOrder) { supplier = 'utt'; reference = String(u.order.idOrder); }
  else if (u) rawError = u.error || u.message || JSON.stringify(u).slice(0, 300);
} catch (e) {}
if (!supplier) {
  try {
    const f = $('External: Buy Coins').first().json;
    const p = typeof f.data === 'string' ? JSON.parse(f.data) : (f.data || f);
    if (p && p.orderID) { supplier = 'fft'; reference = String(p.orderID); }
    else if (p) rawError = (p.error && p.error.message) || p.error || p.message || JSON.stringify(p).slice(0, 300);
  } catch (e) {}
}

if (!supplier) {
  const detail = rawError ? String(rawError) : 'لم يصدر رقم طلب';
  const hint = /429|[Tt]oo [Mm]any/.test(detail) ? ' — غالباً ضغط طلبات (rate limit)' : '';
  throw new Error(`[place] order ${orderId}: المورد رفض طلب الشحن: ${detail}${hint}`);
}

return shipment.itemIds.map((orderItemPublicId) => ({
  json: {
    orderId,
    order_item_public_id: orderItemPublicId,
    supplier,
    supplier_order_id: reference,
    delivery_phase: 'coins',
  },
}));

/* eslint-disable */
// ship-coins v1 — one signed placement report per funded item.
//
// The store verifies HMAC-SHA256 over `timestamp\neventId\nrawBody` with
// N8N_FULFILLMENT_SECRET (VerifyN8nFulfillmentSignature). rawBody is the
// exact byte sequence that is signed AND the exact byte sequence the HTTP
// node sends raw, so the signature cannot drift from the payload.

const crypto = require('crypto');
const secret = $('Config').first().json.N8N_FULFILLMENT_SECRET;
if (!secret || /^CONFIGURE_/.test(String(secret)) || String(secret).length < 32) {
    throw new Error('[report] N8N_FULFILLMENT_SECRET is not set in the Config node or shorter than 32 characters');
}

const ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
function ulid() {
    let time = Date.now();
    let timestamp = '';
    for (let index = 0; index < 10; index += 1) {
        timestamp = ALPHABET[time % 32] + timestamp;
        time = Math.floor(time / 32);
    }
    let random = '';
    for (let index = 0; index < 16; index += 1) {
        random += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];
    }
    return timestamp + random;
}

return $input.all().map(({ json }) => {
    const report = {
        order_item_public_id: json.order_item_public_id,
        supplier: json.supplier,
        supplier_order_id: json.supplier_order_id,
        delivery_phase: json.delivery_phase,
    };
    const rawBody = JSON.stringify(report);
    const timestamp = String(Math.floor(Date.now() / 1000));
    const event = ulid();
    const signature = crypto
        .createHmac('sha256', secret)
        .update(`${timestamp}\n${event}\n${rawBody}`)
        .digest('hex');

    return { json: { ...json, rawBody, timestamp, event, signature } };
});

/* eslint-disable */
// ship-coins v1 — every placement report must have landed, then the answer
// for the store.
//
// The report HTTP node runs with neverError + fullResponse, so a refused
// report reaches this node as data rather than as an unhandled node error.
// Anything but 200 with acknowledged:true throws: the placement happened at
// the supplier and the store does not know - the exact case the ops alert is
// for, and the case the store's retry then repairs, since the report endpoint
// is idempotent and a second run reports the same reference again.

const shipment = $('Shipment').first().json;
const orderId = shipment.orderId;
const responses = $input.all();

if (responses.length !== shipment.itemIds.length) {
    throw new Error(`[report] order ${orderId}: ${responses.length} report(s) answered for ${shipment.itemIds.length} item(s)`);
}

function decode(body) {
    if (body == null) return {};
    if (typeof body === 'string') { try { return JSON.parse(body); } catch (e) { return { raw: body }; } }
    return body;
}

const placed = [];
for (const { json } of responses) {
    const status = Number(json.statusCode || 0);
    const body = decode(json.body);
    const data = body && body.data;
    if (status === 200 && data && data.acknowledged === true) {
        placed.push({
            order_item_public_id: data.order_item_public_id,
            supplier: data.supplier,
            supplier_order_id: data.supplier_order_id,
            job_public_id: data.job_public_id,
        });
        continue;
    }
    const error = (body && body.error) || {};
    throw new Error(`[report] order ${orderId}: the store refused the placement report (HTTP ${status} ${error.code || ''} ${error.message || body.message || ''})`.trim());
}

return [{
    json: {
        // Not acknowledged while other shipments remain: the store retries with
        // what is still unplaced, and the next run places the next group.
        acknowledged: Number(shipment.remainingGroups || 0) === 0,
        placed,
        remaining: Number(shipment.remainingGroups || 0),
        orderId,
    },
}];
